from collections.abc import Iterable, Mapping

from .repository import contact_exists, put_contact

EMAIL_FIELDS = frozenset(("email", "name"))


def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)


def _clean_row(row):
    if not isinstance(row, Mapping):
        raise ValueError("each contact row must be an object")
    if set(row.keys()) != EMAIL_FIELDS:
        raise ValueError("each contact row must contain exactly 'email' and 'name'")

    email = row["email"]
    name = row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError("contact 'email' and 'name' must be strings")

    email = email.strip()
    name = name.strip()

    if name == "":
        raise ValueError("contact name must not be empty")
    if email.count("@") != 1:
        raise ValueError("contact email must contain exactly one '@'")
    local, _, domain = email.partition("@")
    if local == "" or domain == "":
        raise ValueError("contact email must have nonempty local and domain parts")
    if any(character.isspace() for character in email):
        raise ValueError("contact email must not contain whitespace")

    return email.lower(), name


def import_contacts(connection, rows):
    if rows is None or isinstance(rows, (str, bytes)) or not isinstance(rows, Iterable):
        raise ValueError("rows must be an iterable of contact rows")

    normalized = []
    seen = set()
    for row in rows:
        email, name = _clean_row(row)
        if email in seen:
            raise ValueError("duplicate contact email in batch: %s" % email)
        seen.add(email)
        normalized.append((email, name))

    summary = {"inserted": 0, "updated": 0}
    if not normalized:
        return summary

    connection.execute("BEGIN")
    try:
        for email, name in normalized:
            if contact_exists(connection, email):
                summary["updated"] += 1
            else:
                summary["inserted"] += 1
            put_contact(connection, email, name)
        connection.commit()
    except BaseException:
        connection.rollback()
        raise
    return summary
